'use strict';

// MODULES //

var Ajv = require( 'ajv' );
var schema = require( '@stdlib/_tools/semantic-document/schema' );
var integrity = require( './integrity.js' );


// VARIABLES //

var validateSchema = validator();


// FUNCTIONS //

/**
* Returns a function to validate a semantic document schema.
*
* @private
* @returns {Function} validation function
*
* @example
* var isValid = validator();
*/
function validator() {
	var opts;
	var ajv;

	opts = {};

	// Collect all errors:
	opts.allErrors = true;

	// Include the schema reference and invalid data in error output:
	opts.verbose = true;

	// Perform "full" validation:
	opts.format = 'full';

	// Create a new `Ajv` instance and compile the schema:
	ajv = new Ajv( opts );
	return ajv.compile( schema() );
}


// MAIN //

/**
* Validates a semantic document.
*
* @param {Object} doc - semantic document
* @returns {boolean} boolean indicating if a value is valid
*/
function validate( doc ) {
	var errors;

	if ( !validateSchema( doc ) ) {
		validate.errors = validateSchema.errors;
		return false;
	}
	errors = integrity( doc );
	validate.errors = ( errors.length ) ? errors : null;
	return errors.length === 0;
}

validate.errors = null;


// EXPORTS //

module.exports = validate;
